\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM archiveoperationlogtab WHERE archive_operation_instance_id BETWEEN -910000004 AND -910000001) THEN RAISE EXCEPTION 'fixture collision'; END IF; END $$;
INSERT INTO archiveoperationlogtab(archive_operation_instance_id,operation_instance_id,operation_id,status,entered_ts,entered_tm,status_ts,status_tm)
SELECT -910000000-n,-910000000-n,35,CASE WHEN n=3 THEN 2 ELSE 3 END,now(),0,now()-CASE WHEN n=2 THEN interval '1 day' ELSE interval '40 days' END,0 FROM generate_series(1,3)n;
INSERT INTO archiveoperationmessagetab(archive_operation_message_id,operation_message_id,operation_instance_id,field_name,message) SELECT -910000000-n,-910000000-n,-910000000-n,'fixture','preserve/expire' FROM generate_series(1,3)n;
INSERT INTO archiveoperationsummarytab(archive_operation_summary_id,operation_instance_id) SELECT -910000000-n,-910000000-n FROM generate_series(1,3)n;
INSERT INTO archivexferhist(id,operationid,xferdatetime) VALUES(-910000001,-910000001,now()-interval '40 days'),(-910000002,-910000001,now());
WITH expired AS MATERIALIZED (SELECT l.archive_operation_instance_id,l.operation_instance_id FROM public.archiveoperationlogtab l WHERE l.status IN (1,3,4,5,6) AND l.status_ts < (now() AT TIME ZONE 'UTC') - interval '30 days' AND NOT EXISTS (SELECT 1 FROM public.operationlogtab live WHERE live.operation_instance_id=l.operation_instance_id AND live.status IN (0,2)) AND NOT EXISTS (SELECT 1 FROM public.archiveoperationlogtab newer WHERE newer.operation_instance_id=l.operation_instance_id AND (newer.status IN (0,2) OR newer.status_ts >= (now() AT TIME ZONE 'UTC') - interval '30 days')) ORDER BY l.status_ts LIMIT 1000 FOR UPDATE OF l SKIP LOCKED), messages AS (DELETE FROM public.archiveoperationmessagetab WHERE operation_instance_id IN (SELECT operation_instance_id FROM expired)), summaries AS (DELETE FROM public.archiveoperationsummarytab WHERE operation_instance_id IN (SELECT operation_instance_id FROM expired)), logs AS (DELETE FROM public.archiveoperationlogtab WHERE archive_operation_instance_id IN (SELECT archive_operation_instance_id FROM expired)), transfers AS (DELETE FROM public.archivexferhist WHERE id IN (SELECT t.id FROM public.archivexferhist t WHERE t.xferdatetime < (now() AT TIME ZONE 'UTC') - interval '30 days' AND NOT EXISTS (SELECT 1 FROM public.operationlogtab live WHERE live.operation_id=t.operationid AND live.status IN (0,2)) ORDER BY t.xferdatetime LIMIT 1000 FOR UPDATE OF t SKIP LOCKED) RETURNING 1) SELECT (SELECT count(*) FROM expired)+(SELECT count(*) FROM transfers);
DO $$ BEGIN
IF EXISTS(SELECT 1 FROM archiveoperationlogtab WHERE archive_operation_instance_id=-910000001) OR EXISTS(SELECT 1 FROM archiveoperationmessagetab WHERE operation_instance_id=-910000001) OR EXISTS(SELECT 1 FROM archiveoperationsummarytab WHERE operation_instance_id=-910000001) THEN RAISE EXCEPTION 'expired archive retained'; END IF;
IF (SELECT count(*) FROM archiveoperationlogtab WHERE archive_operation_instance_id IN(-910000002,-910000003))<>2 OR (SELECT count(*) FROM archiveoperationmessagetab WHERE operation_instance_id IN(-910000002,-910000003))<>2 THEN RAISE EXCEPTION 'fresh/active archive lost'; END IF;
IF EXISTS(SELECT 1 FROM archivexferhist WHERE id=-910000001) OR NOT EXISTS(SELECT 1 FROM archivexferhist WHERE id=-910000002) THEN RAISE EXCEPTION 'transfer retention failed'; END IF;
RAISE NOTICE 'PASS: expired archives and children purged; fresh/active records preserved; transfer age respected';
END $$;
ROLLBACK;
